(3194592, 448205, 70000, '<td valign="top">Cute Idea but the random spots where it is out of focus are destracting.</td>', 'Cute Idea but the random spots where it is out of focus are destracting.', '2007-01-08 02:58:33.000000', NULL, 1),
(3194594, 448694, 70000, '<td valign="top">I love the motion and range in this photograph. Even though the runner is so small I am still drawn by the lines to the subject. I love it.</td>', 'I love the motion and range in this photograph. Even though the runner is so small I am still drawn by the lines to the subject. I love it.', '2007-01-08 02:59:27.000000', NULL, 1),
(3194596, 448343, 70000, '<td valign="top">haha, I was going to criticize this picture because the painter has no paint on him...then I remembered "Procrastination" which would be exactly why he is spotless. The picture looks a bit set up for my taste but I still love it. Its well lit and really fits the challenge.</td>', 'haha, I was going to criticize this picture because the painter has no paint on him...then I remembered "Procrastination" which would be exactly why he is spotless. The picture looks a bit set up for my taste but I still love it. Its well lit and really fits the challenge.', '2007-01-08 03:01:13.000000', NULL, 1),
(3194597, 449335, 70000, '<td valign="top">I like the idea but the candle seems a bit blown and the crop is a bit tight on the left side.</td>', 'I like the idea but the candle seems a bit blown and the crop is a bit tight on the left side.', '2007-01-08 03:02:12.000000', NULL, 1),
(3194600, 449331, 70000, '<td valign="top">haha touche. Nice use of the color dynamics between the red and the green.</td>', 'haha touche. Nice use of the color dynamics between the red and the green.', '2007-01-08 03:03:01.000000', NULL, 1);
