(3227904, 448851, 36403, '<td valign="top">Very cool ~ love the smoke on the black background.</td>', 'Very cool ~ love the smoke on the black background.', '2007-01-13 22:12:00.000000', NULL, 1),
(3227913, 447135, 36403, '<td valign="top">I get that you''re wanting to show the clutter here, but it still looks too much like a cluttered snapshot for my taste.  Maybe trying a different perspecitve would help?</td>', 'I get that you''re wanting to show the clutter here, but it still looks too much like a cluttered snapshot for my taste.  Maybe trying a different perspecitve would help?', '2007-01-13 22:14:22.000000', NULL, 1),
