(3227923, 448915, 36403, '<td valign="top">LOL  Nice title.  I like the perpective.  7</td>', 'LOL  Nice title.  I like the perpective.  7', '2007-01-13 22:16:53.000000', NULL, 1),
(3227932, 448978, 66524, '<td valign="top">Your theme is great. Left side of photo is quite pleasing (beige garment folds, reddish sweater sleeve focus &amp; light), striped garment divides and makes the right side glare in white tones and makes it difficult to look at the photo as a whole - I look at 1 side or the other...like 2 photos.</td>', 'Your theme is great. Left side of photo is quite pleasing (beige garment folds, reddish sweater sleeve focus & light), striped garment divides and makes the right side glare in white tones and makes it difficult to look at the photo as a whole - I look at 1 side or the other...like 2 photos.', '2007-01-13 22:18:43.000000', NULL, 1),
(3227938, 449212, 36403, '<td valign="top">Glad you decided not to put that off any more... 5</td>', 'Glad you decided not to put that off any more... 5', '2007-01-13 22:20:27.000000', NULL, 1),
(3227946, 448565, 36403, '<td valign="top">Nice choice for b&amp;w here.  I like the texture in the asphault.  That guy doesn''t look like he''s on vacation, though!  6</td>', 'Nice choice for b&w here.  I like the texture in the asphault.  That guy doesn''t look like he''s on vacation, though!  6', '2007-01-13 22:22:00.000000', NULL, 1),
